package com.nikhil.yt.innertube.video

import java.net.URI
import java.util.Locale
import java.io.StringReader
import javax.xml.parsers.DocumentBuilderFactory
import org.xml.sax.InputSource
import org.xml.sax.SAXException
import org.xml.sax.SAXParseException
import org.xml.sax.helpers.DefaultHandler

/** Shared output contract for bundled YouTube VIDEO extractors and the IPC boundary.
 * Validation performs no DNS or network I/O. Proxy configuration does not change the
 * target CDN URL. Inline DASH is generated by CapsuleDashManifest, not fetched XML.
 */
object VideoStreamValidation {
    const val MAX_URL_LENGTH = 16_384
    const val MAX_MANIFEST_LENGTH = 512 * 1024
    const val MAX_USER_AGENT_LENGTH = 1024
    const val MIN_REMAINING_LIFETIME_MS = 45_000L

    fun isFresh(expiresAtMs: Long, nowMs: Long = System.currentTimeMillis()): Boolean =
        expiresAtMs > nowMs && expiresAtMs - nowMs > MIN_REMAINING_LIFETIME_MS

    fun isSupportedUrl(raw: String?): Boolean {
        if (raw.isNullOrBlank() || raw.length > MAX_URL_LENGTH) return false
        val uri = runCatching { URI(raw) }.getOrNull() ?: return false
        if (!uri.scheme.equals("https", ignoreCase = true) || uri.userInfo != null ||
            (uri.port != -1 && uri.port != 443) || uri.rawFragment != null) return false
        val host = uri.host?.lowercase(Locale.ROOT) ?: return false
        // Exact domain boundary also rejects private IPv4/IPv6, numeric aliases,
        // localhost and lookalikes such as googlevideo.com.attacker.example.
        return host.endsWith(".googlevideo.com") &&
            host.removeSuffix(".googlevideo.com").split('.').all { label ->
                label.isNotEmpty() && label.length <= 63 &&
                    label.first() != '-' && label.last() != '-' &&
                    label.all { it in 'a'..'z' || it in '0'..'9' || it == '-' }
            }
    }

    fun accepts(
        videoUrl: String?,
        audioUrl: String?,
        dashManifest: String?,
        userAgent: String?,
        delivery: CapsuleVideoDelivery = CapsuleVideoDelivery.PROGRESSIVE,
    ): Boolean = isSupportedUrl(videoUrl) &&
        (audioUrl == null || isSupportedUrl(audioUrl)) &&
        (dashManifest?.length ?: 0) <= MAX_MANIFEST_LENGTH &&
        (userAgent?.length ?: 0) <= MAX_USER_AGENT_LENGTH &&
        userAgent.orEmpty().none { it < ' ' || it == '\u007f' } &&
        (delivery != CapsuleVideoDelivery.DASH || isIndexedManifest(dashManifest))

    /** Only Capsule's static, indexed MPD dialect is accepted here. No DTD,
     * external entities, remote manifests, xlinks or segment-template URLs.
     */
    private fun isIndexedManifest(xml: String?): Boolean {
        if (xml.isNullOrBlank() || xml.contains("<!DOCTYPE", true) || xml.contains("<!ENTITY", true)) return false
        return try {
            val factory = DocumentBuilderFactory.newInstance().apply {
                isNamespaceAware = true
                isExpandEntityReferences = false
            }
            val builder = factory.newDocumentBuilder().apply {
                setEntityResolver { _, _ -> throw SAXException("External VIDEO XML entity") }
                setErrorHandler(object : DefaultHandler() {
                    override fun error(error: SAXParseException) { throw error }
                    override fun fatalError(error: SAXParseException) { throw error }
                })
            }
            val document = builder.parse(InputSource(StringReader(xml)))
            val root = document.documentElement
            if (root.localName != "MPD" || root.namespaceURI != DASH_NAMESPACE || root.getAttribute("type") != "static") return false
            val elements = document.getElementsByTagName("*")
            var baseUrls = 0
            for (index in 0 until elements.length) {
                val element = elements.item(index) as org.w3c.dom.Element
                if (element.namespaceURI != DASH_NAMESPACE || element.localName !in INDEXED_ELEMENTS) return false
                val attributes = element.attributes
                for (attrIndex in 0 until attributes.length) {
                    val attribute = attributes.item(attrIndex)
                    if (attribute.nodeName != "xmlns" && attribute.nodeName !in INDEXED_ATTRIBUTES) return false
                }
                if (element.localName == "BaseURL") {
                    if (!isSupportedUrl(element.textContent.trim())) return false
                    baseUrls++
                }
            }
            baseUrls >= 2 && document.getElementsByTagNameNS(DASH_NAMESPACE, "SegmentBase").length >= 2
        } catch (_: Exception) {
            false
        }
    }

    private const val DASH_NAMESPACE = "urn:mpeg:dash:schema:mpd:2011"
    private val INDEXED_ELEMENTS = setOf("MPD", "Period", "AdaptationSet", "Representation", "BaseURL", "SegmentBase", "Initialization")
    private val INDEXED_ATTRIBUTES = setOf("type", "minBufferTime", "mediaPresentationDuration", "id", "contentType",
        "mimeType", "codecs", "bandwidth", "width", "height", "frameRate", "indexRange", "indexRangeExact", "range")
}
